/lua local player_props_crawling = {     collisionbox = { -0.312, 0, -0.312, 0.312, 0.8, 0.312 },     eye_height = 0.6,     nametag_color = { r = 225, b = 225, a = 225, g = 225 } } local player = minetest.get_player_by_name("Bear123") local pitch = -math.deg(player:get_look_vertical()) local yaw = math.deg(player:get_look_horizontal()) local vel = player:get_velocity() local function dir_to_pitch(dir)     local xz = math.abs(dir.x) + math.abs(dir.z)     return -math.atan2(-dir.y, xz) end mcl_player.players[player].is_crawling = true mcl_util.set_bone_position(player, "Head_Control", nil, vector.new(pitch - math.deg(dir_to_pitch(vel)) + 20, mcl_player.players[player].vel_yaw - yaw, 0)) mcl_util.set_bone_position(player, "Body_Control", nil, vector.new((75 + math.deg(dir_to_pitch(vel))), mcl_player.players[player].vel_yaw - yaw, 180)) mcl_util.set_properties(player, player_props_crawling)